#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
#include <climits>
#include <cstdio>
using namespace std;

using i64 = long long;

const int INF = 0x7f7f7f7f;
const int MAX_EDGE_COUNT = 5010000;
const int MOD = 1000000007;

struct Arc {
    int dest;
    int cap;
    int cost;
    int next;
};

vector<Arc> arcs;
vector<int> head;

void connect(int u, int v, int capacity, int cost) {
    arcs.push_back({v, capacity, cost, head[u]});
    head[u] = static_cast<int>(arcs.size()) - 1;
    arcs.push_back({u, 0, -cost, head[v]});
    head[v] = static_cast<int>(arcs.size()) - 1;
}

void scan(int &value) {
    value = 0;
    char ch = getchar();
    while (ch < '0' || ch > '9') {
        if (ch == '-') break;
        ch = getchar();
    }
    bool negative = false;
    if (ch == '-') {
        negative = true;
        ch = getchar();
    }
    while (ch >= '0' && ch <= '9') {
        value = value * 10 + (ch - '0');
        ch = getchar();
    }
    if (negative) value = -value;
}

void output(int value) {
    if (value < 0) {
        putchar('-');
        value = -value;
    }
    if (value > 9) output(value / 10);
    putchar(value % 10 + '0');
}

void println(int value) {
    output(value);
    putchar('\n');
}

int source, target;
vector<int> dist, flow, prevNode, prevArc;
vector<bool> visited;

bool bellman_ford() {
    fill(dist.begin(), dist.end(), INF);
    fill(flow.begin(), flow.end(), 0);
    fill(prevNode.begin(), prevNode.end(), -1);
    fill(prevArc.begin(), prevArc.end(), -1);
    fill(visited.begin(), visited.end(), false);

    queue<int> q;
    dist[source] = 0;
    flow[source] = INF;
    q.push(source);
    visited[source] = true;

    while (!q.empty()) {
        int u = q.front();
        q.pop();
        visited[u] = false;

        for (int idx = head[u]; idx != -1; idx = arcs[idx].next) {
            int v = arcs[idx].dest;
            int cap = arcs[idx].cap;
            int cost = arcs[idx].cost;

            if (cap > 0 && dist[v] > dist[u] + cost) {
                dist[v] = dist[u] + cost;
                flow[v] = min(flow[u], cap);
                prevNode[v] = u;
                prevArc[v] = idx;
                if (!visited[v]) {
                    q.push(v);
                    visited[v] = true;
                }
            }
        }
    }

    return prevNode[target] != -1;
}

int maxFlow, minCost;

void minCostFlow() {
    while (bellman_ford()) {
        int augment = flow[target];
        maxFlow += augment;
        minCost += augment * dist[target];

        int node = target;
        while (node != source) {
            arcs[prevArc[node]].cap -= augment;
            arcs[prevArc[node] ^ 1].cap += augment;
            node = prevNode[node];
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, k, c, d;
    scan(n); scan(m); scan(k); scan(c); scan(d);

    int B = max(n, k);
    source = n * (2 * B + 1) + 1;
    target = source + 1;

    dist.resize(target + 1);
    flow.resize(target + 1);
    prevNode.resize(target + 1);
    prevArc.resize(target + 1);
    visited.resize(target + 1);
    head.assign(target + 1, -1);

    for (int i = 0; i < k; i++) {
        int x;
        scan(x);
        connect(source, x, 1, 0);
    }

    connect(n * (2 * B) + 1, target, INF, 0);

    for (int layer = 0; layer < 2 * B; layer++) {
        connect(layer * n + 1, (layer + 1) * n + 1, INF, 0);
        for (int i = 2; i <= n; i++) {
            connect(layer * n + i, (layer + 1) * n + i, INF, c);
        }
    }

    for (int i = 0; i < m; i++) {
        int x, y;
        scan(x); scan(y);
        for (int layer = 0; layer < 2 * B; layer++) {
            for (int j = 1; j <= k; j++) {
                int cost = d * (2 * j - 1) + c;
                connect(layer * n + x, (layer + 1) * n + y, 1, cost);
                connect(layer * n + y, (layer + 1) * n + x, 1, cost);
            }
        }
    }

    minCostFlow();
    println(minCost);

    return 0;
}
